//! `generated_edit.rs` — a file a program owns is being edited by hand (`e4.3`).
//!
//! **What it claims.** This path is derived — the index classed it generated, or the file's own banner
//! says so — and lines were added to it. The finding is a question with a named alternative: *was this the
//! generator, or was it a person?*
//!
//! **The honest difficulty, stated as two downgrades rather than hidden in a threshold.** A generated file
//! legitimately changes in a commit: that is how generated files get updated. The two shapes are:
//!
//! * **the codegen run**, where the episode also touches the template or the schema that produced the
//!   output. Then the change is expected and the finding drops to `low` and says which file gave it away
//!   ([`generator_touched`]);
//! * **the stamp**, where the only lines that moved are a `Timestamp:`, a `Version:` or the banner's own
//!   date. That is not a hand-edit and not a finding at all ([`stamp_only`]) — printing it would put a
//!   row on every regeneration in the corpus.
//!
//! **Two evidence sources, and they price differently.** The stored taxonomy (`path_class`/`noise_class`
//! from `e0.9`) is the repository's own assertion and gets `0.65`. A banner visible in the hunks — which
//! happens only when the top of the file changed — is the file asserting it, and gets `0.55`, because a
//! banner in a diff hunk can also be the *removal* of a banner, which is a person deleting the warning
//! from a file they are about to hand-edit. Both are printed in the evidence, so the reviewer sees which
//! kind of claim they are reading.
//!
//! **Snapshot output** (`__snapshots__/`, `*.snap`, `*.min.js`) is generated by a test run rather than by a
//! generator, and the diff cannot tell a re-record from a hand-tweak. It is reported at `low`, once, and
//! the message says the file's re-record is the normal case.

use crate::detectors::finding::{Evidence, EvidenceKind, Finding, Severity};
use crate::detectors::model::{Corpus, Episode, FileChange};
use crate::detectors::policy::Policy;
use crate::detectors::text;
use crate::risk::Surface;

/// A line a code generator stamps. A change that touches only these is a re-run, not an edit.
const STAMP_WORDS: &[&str] = &[
    "timestamp",
    "generated",
    "generation time",
    "version",
    "date",
    "revision",
    "source hash",
    "do not edit",
];

/// A file whose own header says it is derived.
const BANNERS: &[&str] = &[
    "DO NOT EDIT",
    "do not modify by hand",
    "Code generated by",
    "Generated by",
    "auto-generated",
    "autogenerated",
    "auto generated",
    "@generated",
    "<auto-generated>",
    "This file was generated",
    "gogen",
    "protoc-gen",
    "generated by protoc",
    "don't edit this file",
];

/// A file whose presence in the same episode says "this was the codegen run".
const GENERATORS: &[&str] = &[
    "codegen/",
    "generator/",
    "generators/",
    "build.rs",
    "generate.go",
    "gen.go",
    "generate.py",
    "codegen.py",
    "build.gradle",
    ".proto",
    "schema.graphql",
    "openapi.yaml",
    "openapi.json",
    "schema.sql",
    "makefile",
];

/// Output that a test run re-records rather than a program generating.
const SNAPSHOT_MARKERS: &[&str] = &[
    "__snapshots__/",
    ".snap",
    ".min.js",
    ".min.css",
    "storybook-static/",
];

pub fn detect(episode: &Episode, _corpus: &Corpus<'_>, policy: &Policy) -> Vec<Finding> {
    let generators = episode
        .files
        .iter()
        .filter_map(|file| generator_marker(&file.path))
        .collect::<Vec<_>>();

    episode
        .files
        .iter()
        .filter(|file| !file.binary && !file.is_delete() && file.add > 0)
        .filter_map(|file| {
            let classed = is_classed_generated(file);
            let banners: Vec<&str> = file
                .added()
                .into_iter()
                .filter(|line| BANNERS.iter().any(|banner| line.contains(banner)))
                .collect();
            if !classed && banners.is_empty() {
                return None;
            }
            let all_lines: Vec<String> = file
                .added()
                .into_iter()
                .chain(file.removed())
                .map(text::normalise)
                .filter(|line| !line.is_empty())
                .collect();
            if all_lines.is_empty() {
                return None;
            }
            if stamp_only(&all_lines) {
                // A regeneration's stamp. Not a finding, and not a gap either: nothing was hidden, the
                // change simply is what the repository does when the generator runs.
                return None;
            }
            let snapshot = SNAPSHOT_MARKERS.iter().any(|marker| file.path.contains(marker));
            let via_generator = !generators.is_empty();
            let severity = if snapshot || via_generator {
                Severity::Low
            } else {
                Severity::Medium
            };
            let confidence = if classed { 0.65 } else { 0.55 };

            let mut reason = if classed {
                format!(
                    "{} is a generated file (the index classes it {}), and {} hand-written line(s) were added to it",
                    file.path, file.taxonomy_label(), file.add
                )
            } else {
                format!(
                    "{} says it is generated — {} — and {} line(s) were added to it",
                    file.path,
                    crate::detectors::quote(&banners, 1),
                    file.add
                )
            };
            if snapshot {
                reason.push_str(
                    " — this is recorded output a test run re-writes, so the ordinary case is a \
                     re-recording and this diff cannot tell the two apart",
                );
            }
            if let Some(generator) = generators.first() {
                reason.push_str(&format!(
                    " — the episode also touched {generator}, which may be the run that produced this"
                ));
            }

            let mut finding = Finding::build("generated_edit", 1, &episode.id, file.path.clone(), reason)
                .severity(severity)
                .confidence(confidence)
                .evidence(Evidence::asserted(
                    EvidenceKind::Path,
                    file.path.clone(),
                    if classed {
                        format!(
                            "stored taxonomy: path_class={}, noise_class={}",
                            if file.path_class.is_empty() { "unknown" } else { &file.path_class },
                            if file.noise_class.is_empty() { "unknown" } else { &file.noise_class }
                        )
                    } else {
                        format!("banner in the diff: {}", crate::detectors::quote(&banners, policy.evidence_lines))
                    },
                ))
                .jump_path(&file.path);
            if let Some(generator) = generators.first() {
                finding = finding.evidence(Evidence::inferred(
                    EvidenceKind::Path,
                    (*generator).to_owned(),
                    "touched by the same episode: a template, a schema or a build script",
                ));
            }
            Some(finding.finish())
        })
        .collect()
}

/// The taxonomy's own answer, from the two columns `e0.9` writes.
fn is_classed_generated(file: &FileChange) -> bool {
    file.path_class == "generated"
        || file.noise_class == "generated"
        || file.surface() == Surface::Generated
}

/// A path that says where generated output comes from, when the episode touched one.
fn generator_marker(path: &str) -> Option<String> {
    let folded = path.to_ascii_lowercase();
    GENERATORS
        .iter()
        .copied()
        .find(|needle| folded.contains(needle))
        .map(str::to_owned)
        .or_else(|| {
            // A script whose *name* says it generates, without being in the table.
            let name = folded.rsplit('/').next().unwrap_or(folded.as_str());
            (name.starts_with("generate") || name.starts_with("gen_") || name.ends_with("_gen.py"))
                .then(|| path.to_owned())
        })
}

/// Every changed line is a stamp: a date, a version, or the banner itself.
fn stamp_only(lines: &[String]) -> bool {
    !lines.iter().any(|line| {
        let folded = line.to_ascii_lowercase();
        !STAMP_WORDS.iter().any(|word| folded.contains(word))
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::detectors::model::{Content, Hunk, change};

    fn file(path: &str, added: &[&str]) -> FileChange {
        FileChange {
            path: path.to_owned(),
            change: change::MODIFIED.to_owned(),
            add: added.len() as i64,
            hunks: vec![Hunk::new(
                "@@ -1,2 +1,4 @@",
                added.to_vec(),
                Vec::<String>::new(),
            )],
            ..Default::default()
        }
    }

    fn episode(files: Vec<FileChange>) -> Episode {
        Episode {
            id: "ep-1".to_owned(),
            files,
            content: Content::Full,
            ..Episode::new("ep-1")
        }
    }

    #[test]
    fn a_taxonomy_generated_file_with_hand_lines_is_a_finding() {
        let mut case = file(
            "api/handlers.rs",
            &["    if req.is_admin() { return ok(); }"],
        );
        case.path_class = "generated".to_owned();
        case.noise_class = "generated".to_owned();
        let findings = detect(&episode(vec![case]), &Corpus::default(), &Policy::default());
        assert_eq!(findings.len(), 1);
        let finding = &findings[0];
        assert_eq!(finding.detector_id, "generated_edit");
        assert_eq!(finding.severity, Severity::Medium);
        assert!((finding.confidence - 0.65).abs() < f64::EPSILON);
        assert!(finding.evidence[0].detail.contains("path_class=generated"));
        assert_eq!(finding.suppression_key, "generated_edit:api/handlers.rs");
    }

    #[test]
    fn a_banner_in_the_file_asserts_it_itself() {
        let case = file(
            "internal/wire.go",
            &[
                "// Code generated by wire. DO NOT EDIT.",
                "func ProvideCache() *Cache { return nil }",
            ],
        );
        let findings = detect(&episode(vec![case]), &Corpus::default(), &Policy::default());
        assert_eq!(findings.len(), 1);
        assert!(
            (findings[0].confidence - 0.55).abs() < f64::EPSILON,
            "a banner is a weaker source than the taxonomy"
        );
        assert!(
            findings[0].message.contains("says it is generated"),
            "{}",
            findings[0].message
        );
    }

    #[test]
    fn a_regeneration_in_the_same_episode_is_low_and_says_which_file_said_so() {
        let schema = file("openapi.yaml", &["    /v2/items:"]);
        let mut generated = file("api/handlers.rs", &["fn list_items() {}"]);
        generated.path_class = "generated".to_owned();
        let findings = detect(
            &episode(vec![schema, generated]),
            &Corpus::default(),
            &Policy::default(),
        );
        assert_eq!(findings.len(), 1);
        assert_eq!(findings[0].severity, Severity::Low);
        assert!(
            findings[0].message.contains("openapi.yaml"),
            "{}",
            findings[0].message
        );
    }

    #[test]
    fn a_stamp_change_is_not_a_finding() {
        let mut case = file(
            "api/handlers.rs",
            &[
                "// Timestamp: 2026-10-19T00:00:00Z",
                "// Version: 0.3.1",
                "// generated by build.rs",
            ],
        );
        case.path_class = "generated".to_owned();
        assert!(
            detect(&episode(vec![case]), &Corpus::default(), &Policy::default()).is_empty(),
            "a re-run that moved only the stamp is what a codegen commit looks like"
        );
    }

    #[test]
    fn a_snapshot_re_record_is_a_note_and_not_an_accusation() {
        let case = file("tests/__snapshots__/card.snap", &["+header row"]);
        let findings = detect(&episode(vec![case]), &Corpus::default(), &Policy::default());
        assert_eq!(findings.len(), 1);
        assert_eq!(findings[0].severity, Severity::Low);
        assert!(
            findings[0].message.contains("re-record"),
            "{}",
            findings[0].message
        );
    }

    #[test]
    fn an_ordinary_source_file_is_not_considered() {
        let case = file("src/parser.rs", &["fn parse() {}"]);
        assert!(detect(&episode(vec![case]), &Corpus::default(), &Policy::default()).is_empty());
    }

    #[test]
    fn a_deleted_generated_file_is_not_a_hand_edit() {
        let mut case = file("api/handlers.rs", &[]);
        case.change = change::DELETED.to_owned();
        case.del = 40;
        case.path_class = "generated".to_owned();
        assert!(detect(&episode(vec![case]), &Corpus::default(), &Policy::default()).is_empty());
    }
}
